/* ---------- agent settings ---------- */
{
  const desc = $('#as-desc'), state = $('#as-state'), save = $('#as-save'), sendT = $('[data-k="send"]', $('#as')), sendLine = $('#as-send-line');
  const texts = ['Checks with you before every step, so nothing happens without your go-ahead.','Runs routine steps on its own and checks with you before sending, deleting or spending.','Works through the whole task on its own and reports back when it is done.'];
  function dirty(){ save.disabled = false; state.classList.add('dirty'); swapText(state, 'Unsaved changes'); }
  function lock(level){ const on = level === '2'; sendT.disabled = !on; sendLine.classList.toggle('locked', !on); if (!on) sendT.setAttribute('aria-checked', 'false'); }
  segInit($('#as-seg'), v => { swapText(desc, texts[+v]); lock(v); dirty(); });
  $$('#as .tg').forEach(t => t.addEventListener('click', () => { if (t.disabled) return; const on = t.getAttribute('aria-checked') !== 'true'; t.setAttribute('aria-checked', on); Sound.play(on ? 'on' : 'off'); dirty(); }));
  $('#as-model').addEventListener('change', () => { Sound.play('tab'); dirty(); });
  save.addEventListener('click', () => { save.disabled = true; state.classList.remove('dirty'); swapText(state, 'Saved just now'); Sound.play('done'); });
  lock('1');
}
